 private static final Map<UUID,State> states=new HashMap<>(),copies=new HashMap<>();
 private static final Map<UUID,Visual> visuals=new HashMap<>();private static final Map<UUID,Snare> snares=new HashMap<>();private static final Map<UUID,Long> resistance=new HashMap<>(),cardResistance=new HashMap<>(),landing=new HashMap<>();
 private static final List<Blast> blasts=new ArrayList<>();private static final Set<UUID> moving=new HashSet<>();private static final ThreadLocal<Boolean> transfer=ThreadLocal.withInitial(()->false),masterElement=ThreadLocal.withInitial(()->false);
 private static final class PowerShot {Player owner;ServerLevel level;String fruit;Vec3 at,dir;int kind,age;float damage;double range,width,speed,radius;long launch;boolean launched;Display.BlockDisplay visual;final Set<UUID> hit=new HashSet<>();}
